/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.stockDutyarr =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05103' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05103.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_stockDutyList_oncellclick
 * @description grd_stockDutyList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_stockDutyList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_stockDutyList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_stockDutyList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.openStockDutyWin(r["bzProcsNo"], r["prtdepoId"], r["listProcsStatCd"]); return;
        if (String(r["listProcsStatCd"]) === "35") { await scwin.openStockDutyWin(r["bzProcsNo"], r["prtdepoId"], r["listProcsStatCd"]); return; }
        if (String(r["listProcsStatCd"]) === "37") { await scwin.openStockDutyWin(r["bzProcsNo"], r["prtdepoId"], r["listProcsStatCd"]); return; }
        await scwin.stockDutySubmit(r["bzProcsNo"], r["prtdepoId"], "32", r["index"]); return;
        if (String(r["listProcsStatCd"]) === "33") { await scwin.openAdjReqWin(r["bzProcsNo"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_stockDutyList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_openStockDutyWin_4_onclick
