 * @returns
 * @hidden N
 */
// TODO Stage2: 공급사 산출의 중복 정의(둘째 본문 — 첫째와 다름, 어느 쪽이 맞는지 판단) — 원이름 grd_stockDutyList_oncellclick

/**
 * @method
 * @name grd_stockDutyList_oncellclick_2
 * @description grd stock Duty List oncellclick 2 처리
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_stockDutyList_oncellclick_2 = function (rowIndex, columnIndex, columnId) {
    try { if (columnId === '_del') { const d = $c.util.getComponent('dlt_stockDutyList'); if (d && d.removeRow) { d.removeRow(rowIndex); }  return; }
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05103.grd_stockDutyList_oncellclick' }); }
};

