/**
 * @method
 * @name tx_fn_openStockDutyWin
 * @description open Stock Duty Win 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_openStockDutyWin = async function () {
    const sbmOptions = {
        id: "tx_fn_openStockDutyWin",
        method: "post",
        action: "/list/listShrs.do",
        ref: "dma_openStockDutyWinReq",
        target: "dlt_stockDutyList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

