 */
scwin.deleteRow = function (obj) {
    const table = obj.parentNode.parentNode.parentNode.parentNode;
    table.deleteRow(obj.parentNode.parentNode.rowIndex);
};

/**
 * @method
 * @name openStockDutyWin
 * @description open Stock Duty Win 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} prtdepoId prtdepoId
 * @param {String} listProcsStatCd listProcsStatCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openStockDutyWin = async function (bzProcsNo, prtdepoId, listProcsStatCd) {
    const stockDutyWin = {};
    stockDutyWin.calcelYn = 'Y';
    const url = "/jldfil05105/jldfil05105.xml?method=selectStockDuty&isurCd=" + "${session.company.isurCd }&prtdepoId=" + prtdepoId + "&bzProcsNo=" + bzProcsNo + "&listProcsStatCd=" + listProcsStatCd;
    const style = "dialogWidth:730px;dialogHeight:430px;scroll:no;resize:no";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    Object.assign(stockDutyWin, (await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { type: 'pageFramePopup', modal: true }, stockDutyWin)) || {});
    if (stockDutyWin.calcelYn === 'N') {
        $c.win.setPageFrameSrc($c.win.getFrame(), null);
    }
    await scwin.tx_fn_openStockDutyWin();

};

/**
 * @method
 * @name checkDate
 * @description check Date 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.checkDate = function (val) {
    if (val.length === 0) {
        return true;
    }
    if (val.length !== 8) {
        return false;
    }
    const year = val.substring(0, 4);
    const month = val.substring(4, 6);
    const day = val.substring(6, 8);
    if (month > 12 || month < 1) {
        return false;
    }
    if (month === 2 || month === 02) {
        if (day > 29 || day < 1) {
            return false;
        }
    } else {
        if (month === 1 || month === 3 || month === 5 || month === 7 || month === 8 || month === 10 || month === 12) {
            if (day > 31 || day < 1) {
                return false;
            }
        } else {
            if (month === 4 || month === 6 || month === 9 || month === 11) {
                if (day > 30 || day < 1) {
                    return false;
                }
            }
        }
    }
    return true;
};

/**
 * @method
 * @name stockDutySubmit
 * @description stock Duty Submit 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} prtdepoId prtdepoId
 * @param {*} updateType updateType
 * @param {Number} cnt cnt
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.stockDutySubmit = async function (bzProcsNo, prtdepoId, updateType, cnt) {
    scwin.form = (document.stockDutySubForm || { elements: [] });
    if (!scwin.checkDate(scwin.stockDutyarr[cnt].prtdepoEndDd) || !scwin.checkDate(scwin.stockDutyarr[cnt].stkoptDutyExerEndDd) || !scwin.checkDate(scwin.stockDutyarr[cnt].stkoptDutyExerStartDd) || !scwin.checkDate(scwin.stockDutyarr[cnt].stkoptDutyResolDd)) {
        await $c.win.alert("날짜 형식이 잘못 되었습니다. 확인 후 수정해 주세요.");
        return;
    }
    const rse = await $c.win.confirm("제출 하시겠습니까? ");
    if (rse) {
        $c.util.getComponent('dma_openStockDutyWinReq').set('bzProcsNo', bzProcsNo);
        $c.util.getComponent('dma_openStockDutyWinReq').set('prtdepoId', prtdepoId);
        $c.util.getComponent('dma_openStockDutyWinReq').set('listProcsStatCd', updateType);
        scwin.form.action = '/list/listDisclosureForm.do';
        $c.util.getComponent("dma_openStockDutyWinReq").set("method", 'stockDutySubmit');
        await scwin.tx_fn_stockDutySubmit();
    }
};

/**
 * @method
 * @name stockDutyRslt
 * @description stock Duty Rslt 처리
 * @param {*} bzProcsNo bzProcsNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.stockDutyRslt = async function (bzProcsNo) {
    const frm = (document.stockDutySubForm || { elements: [] });
    $c.util.getComponent('dma_openStockDutyWinReq').set('bzProcsNo', bzProcsNo);
    frm.action = "stockDutyRslt.do";
    $c.util.getComponent("dma_openStockDutyWinReq").set("method", "searchStockDutyRslt");
    await scwin.tx_fn_stockDutyRslt();
};

